INSERT INTO "statutory_rule_sets" ("statute", "jurisdiction", "version", "valid_from", "valid_to", "values", "source", "verify", "status", "law_version", "published_at") VALUES ('IN.PT', 'IN-WB', '2014-v1', '2014-04-01', '2026-09-30', '{"kind":"pt","basis":"monthly","annualCap":"2500","slabs":[{"from":"0","to":"10000","amount":"0"},{"from":"10000.01","to":"15000","amount":"110"},{"from":"15000.01","to":"25000","amount":"130"},{"from":"25000.01","to":"40000","amount":"150"},{"from":"40000.01","to":null,"amount":"200"}]}', 'West Bengal State Tax on Professions, Trades, Callings and Employments Act, 1979, schedule w.e.f. 1 Apr 2014 (official): https://comtax.wb.gov.in/Ptax-Schedule-New_(w.e.f._1-4-2014).pdf . Monthly: up to 10,000 nil; 10,001-15,000 = 110; 15,001-25,000 = 130; 25,001-40,000 = 150; above 40,000 = 200. In force to 30 Sep 2026 (replaced from 1 Oct 2026). Verify until the CA confirms (checklist items 6 and 24).', true, 'published', 'OLD-ACT', CURRENT_TIMESTAMP);
