INSERT INTO "statutory_rule_sets" ("statute", "jurisdiction", "version", "valid_from", "valid_to", "values", "source", "verify", "status", "law_version", "published_at") VALUES ('IN.PT', 'IN-WB', '2026-v2', '2026-10-01', NULL, '{"kind":"pt","basis":"monthly","annualCap":"2500","slabs":[{"from":"0","to":"20000","amount":"0"},{"from":"20000.01","to":"30000","amount":"100"},{"from":"30000.01","to":"50000","amount":"140"},{"from":"50000.01","to":"100000","amount":"170"},{"from":"100000.01","to":null,"amount":"208"}]}', 'West Bengal PT schedule from 1 Oct 2026 (Act amended by notification 756-L of 07.08.2026; draft schedule 1407-F.T. of 18.08.2026; final number disputed, maybe 1607-F.T. of 16.09.2026). Secondary only: https://www.sgcms.com/regulatory-updates/west-bengal-overhauls-professional-tax-new-schedule-notified/ . Up to 20,000 nil; to 30,000 = 100; to 50,000 = 140; to 1,00,000 = 170; above = 208. TODO: CA checklist item 6.', true, 'published', 'OLD-ACT', CURRENT_TIMESTAMP);
